import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const e="/ascendc.github.io/pr/5487/assets/no_nz2nd_dual_target_mode.CA4xJoL2.png",l="/ascendc.github.io/pr/5487/assets/enable_nz2nd_dual_load.uH77_0t7.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"矩阵计算","link":"/api/SIMD-API/tensor_api/matrix_compute/matrix_compute"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/cube_store_key_features"},{"text":"L0C Buffer到Unified Buffer双目标模式","link":"/api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/l0c_to_ub_dual_dst"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/l0c_to_ub_dual_dst.md","filePath":"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/l0c_to_ub_dual_dst.md","outlineHeaders":[{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"},{"level":2,"title":"NZ2NZ双目标模式","slug":"NZ2NZ双目标模式","link":"#NZ2NZ双目标模式"},{"level":2,"title":"NZ2ND双目标模式","slug":"NZ2ND双目标模式","link":"#NZ2ND双目标模式"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"}],"lastUpdated":1787967772000}'),t={name:"api/SIMD-API/tensor_api/matrix_compute/cube_store_key_features/l0c_to_ub_dual_dst.md"};function o(d,s,_,i,r,u){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>L0C Buffer到Unified Buffer双目标模式</h1><p>L0C Buffer到Unified Buffer（UB）双目标模式用于将同一AI Core内L0C Buffer的矩阵结果拆分后，同时写入两个Vector Core各自的UB。一个AI Core内包含一个Cube Core和两个Vector Core，启用双目标模式后，源矩阵会按指定维度拆分为两部分，前半部分写入SUB BLOCK0，后半部分写入SUB BLOCK1。</p><p>Tensor API通过<code>l0c_to_ub_trait::dual_dst_ctl</code>控制双目标模式。</p><p><code>dual_dst_ctl</code>取值如下：</p><p><strong>表1</strong> dual_dst_mode取值说明</p><table><thead><tr><th>取值</th><th>说明</th></tr></thead><tbody><tr><td><code>dual_dst_mode::disable</code></td><td>单目标模式。整个矩阵写入默认目标UB。</td></tr><tr><td><code>dual_dst_mode::split_m</code></td><td>双目标模式，按M维度拆分。源矩阵拆分为两个形状为<code>M / 2 * N</code>的矩阵，分别写入两个UB。</td></tr><tr><td><code>dual_dst_mode::split_n</code></td><td>双目标模式，按N维度拆分。源矩阵拆分为两个形状为<code>M * N / 2</code>的矩阵，分别写入两个UB。</td></tr></tbody></table><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="n">l0c_to_ub_trait</span><span class="w"> </span><span class="n">l0c_to_ub_trait_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">round_mode</span><span class="o">::</span><span class="n">default_round</span><span class="p">,</span>
<span class="w">    </span><span class="nb">false</span><span class="p">,</span>
<span class="w">    </span><span class="nb">false</span><span class="p">,</span>
<span class="w">    </span><span class="n">dual_dst_mode</span><span class="o">::</span><span class="n">split_m</span>
<span class="p">};</span>

<span class="k">struct</span><span class="w"> </span><span class="nc">copy_l0c_to_ub_trait_custom</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="n">trait_type</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0c_to_ub_trait</span><span class="p">;</span>
<span class="w">    </span><span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">trait_type</span><span class="w"> </span><span class="n">value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">l0c_to_ub_trait_value</span><span class="p">;</span>
<span class="p">};</span>

<span class="n">l0c_to_ub_params</span><span class="w"> </span><span class="n">params</span><span class="p">;</span>
<span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_l0c_to_ub</span><span class="p">{},</span><span class="w"> </span><span class="n">copy_l0c_to_ub_trait_custom</span><span class="p">{}).</span><span class="n">with</span><span class="p">(</span><span class="n">params</span><span class="p">);</span>
<span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">ub</span><span class="p">,</span><span class="w"> </span><span class="n">l0c</span><span class="p">);</span>
</code></pre></div><h2 id="NZ2NZ双目标模式">NZ2NZ双目标模式<a class="header-anchor" href="#NZ2NZ双目标模式">​</a></h2><p>在NZ2NZ搬运场景下，双目标模式支持按M维度拆分和按N维度拆分。结合底层搬运接口说明如下：</p><p>N方向切分示例：</p><ul><li><code>n_size = 32</code>，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li><code>m_size = 48</code>，表示源NZ矩阵中待搬运矩阵在M方向上的大小为48个元素。</li><li><code>src_stride = 64</code>，表示源NZ矩阵中相邻Z排布的起始地址偏移为<code>64 * c0_size</code>。</li><li><code>dst_stride = 64 * C0</code>，表示目的NZ矩阵中相邻Z排布的起始地址偏移为<code>64 * 16</code>个元素。</li></ul><p>M方向切分示例：</p><ul><li><code>n_size = 32</code>，表示源NZ矩阵中待搬运矩阵在N方向上的大小为32个元素。</li><li><code>m_size = 24</code>，表示每个目标UB接收的M方向大小，源矩阵M方向总大小为48个元素。</li><li><code>src_stride = 64</code>，表示源NZ矩阵中相邻Z排布的起始地址偏移为<code>64 * c0_size</code>。</li><li><code>dst_stride = 40 * C0</code>，表示目的NZ矩阵中相邻Z排布的起始地址偏移为<code>40 * 16</code>个元素。</li></ul><p><strong>图1</strong> NZ2NZ双目标搬运模式设置示意图</p><p><img src="`+e+'" alt="NZ2NZ双目标搬运模式设置示意图"></p><h2 id="NZ2ND双目标模式">NZ2ND双目标模式<a class="header-anchor" href="#NZ2ND双目标模式">​</a></h2><p>在NZ2ND搬运场景下，双目标模式也支持按M维度拆分和按N维度拆分。结合底层搬运接口说明如下：</p><ul><li><code>nd_num = 2</code>，表示源NZ矩阵的数目为2。</li><li><code>n_size = 32</code>，表示源NZ矩阵在N方向上的大小为32个元素。</li><li><code>m_size = 48</code>，表示源NZ矩阵在M方向上的大小为48个元素。</li><li><code>src_stride = 64</code>，表示源NZ矩阵中相邻Z排布的起始地址偏移为<code>64 * c0_size</code>。</li><li><code>dst_stride = 64</code>，表示目的ND矩阵每一行中的元素个数为64。</li><li><code>src_nd_stride = 240</code>，表示不同NZ矩阵起始地址之间的间隔为<code>240 * c0_size</code>。</li><li><code>dst_nd_stride = 4096</code>，表示目的相邻ND矩阵起始地址之间的偏移为4096个元素。</li></ul><p><strong>图2</strong> NZ2ND双目标搬运模式设置示意图</p><p><img src="'+l+'" alt="NZ2ND双目标搬运模式设置示意图"></p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>双目标模式仅支持L0C Buffer到UB通路。</li><li>双目标模式支持普通搬运模式NZ2NZ和NZ2ND搬运场景。</li><li>按M维度拆分时，M必须为2的倍数。</li><li>按N维度拆分时，N必须为32的倍数。</li></ul></article></div>',1)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
